def transform(grid):
    height = len(grid)
    width = len(grid[0]) if height > 0 else 0
    # Create a new grid with 180-degree rotation
    new_grid = [[0] * width for _ in range(height)]
    for r in range(height):
        for c in range(width):
            new_grid[height - 1 - r][width - 1 - c] = grid[r][c]
    return new_grid
